{"path":"check_snake.js","content":"// Extracts inline <script> blocks from the snake game HTML and runs
// `node --check` on each one (syntax gate). No shell chaining required.
const fs = require('fs');
const { execFileSync } = require('child_process');

const HTML = 'snake_zai-glm-5.3-flash_01.html';
const html = fs.readFileSync(HTML, 'utf8');
const blocks = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/gi)];

if (blocks.length === 0) {
  console.error('NO_SCRIPT_BLOCKS_FOUND');
  process.exit(2);
}

let failed = false;
blocks.forEach((m, i) => {
  const tmp = `snake_check_tmp_${i}.js`;
  fs.writeFileSync(tmp, m[1]);
  try {
    execFileSync(process.execPath, ['--check', tmp], { stdio: 'inherit' });
    console.log(`BLOCK ${i}: SYNTAX_OK (${m[1].length} chars)`);
  } catch (e) {
    console.error(`BLOCK ${i}: SYNTAX_ERROR`);
    failed = true;
  } finally {
    fs.unlinkSync(tmp);
  }
});

process.exit(failed ? 1 : 0);
"}
